package com.bookstore.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items")
public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id") private Order order; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="book_id") private Book book; @Column(nullable=false) private Integer quantity; @Column(nullable=false,precision=10,scale=2) private BigDecimal unitPrice; @Column(nullable=false,precision=12,scale=2) private BigDecimal subtotal; public Long getId(){return id;} public void setId(Long v){id=v;} public Order getOrder(){return order;} public void setOrder(Order v){order=v;} public Book getBook(){return book;} public void setBook(Book v){book=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public BigDecimal getSubtotal(){return subtotal;} public void setSubtotal(BigDecimal v){subtotal=v;} }
